import{_ as a,o as t,c as r,a5 as o}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"JD10 单词倒排","description":"简单 通过率：26.37% 时间限制：1秒 空间限制：32M 知识点 排序 字符串 描述 对字符串中的所有单词进行倒排。 说明： 1、构成单词的字符只有26个大写或小写英文字母； 2、非构成单词的字符均视为单词间隔符； 3、要求倒排后的单词间隔符以一个空格表示；如果原字符串中相邻。","frontmatter":{"title":"JD10 单词倒排","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"简单 通过率：26.37% 时间限制：1秒 空间限制：32M 知识点 排序 字符串 描述 对字符串中的所有单词进行倒排。 说明： 1、构成单词的字符只有26个大写或小写英文字母； 2、非构成单词的字符均视为单词间隔符； 3、要求倒排后的单词间隔符以一个空格表示；如果原字符串中相邻。","sidebarWeight":72,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/JD10 单词倒排.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD10 单词倒排.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD10 单词倒排.md"}'),n={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD10 单词倒排.md"};function s(d,e,i,l,p,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<div><h1 id="jd10-单词倒排" tabindex="-1">JD10 单词倒排 <a class="header-anchor" href="#jd10-单词倒排" aria-label="Permalink to &quot;JD10 单词倒排&quot;">​</a></h1><blockquote><p>本节目标：理解“JD10 单词倒排”的核心思路，并能把它用于实际开发或面试表达。 简单 通过率：26.37% 时间限制：1秒 空间限制：32M 知识点==排序====字符串== <strong>描述</strong> 对字符串中的所有单词进行倒排。 说明： 1、构成单词的字符只有26个大写或小写英文字母； 2、非构成单词的字符均视为单词间隔符； 3、要求倒排后的单词间隔符以一个空格表示；如果原字符串中相邻单词间有多个间隔符时，倒排转换后也只允许出现一个空格间隔符； 4、每个单词最长20个字母；</p></blockquote><p>数据范围：字符串长度满足 1≤<em>n</em>≤10000 <strong>输入描述：</strong> 输入一行，表示用来倒排的句子 <strong>输出描述：</strong> 输出句子的倒排结果 <strong>示例1</strong> 输入： I am a student ==复制== 输出： student a am I ==复制== <strong>示例2</strong> 输入： $bo*y gi!r#l ==复制== 输出： l r gi y bo</p><p>为了实现这个要求，我们可以采取以下步骤：</p><ol><li>首先，使用正则表达式来匹配并分割字符串中的单词。这里的“单词”定义为由26个英文字母（大写或小写）构成的字符串。</li><li>接着，将匹配到的单词列表反转。</li><li>最后，将反转后的单词列表用一个空格连接成新的字符串，并输出。</li></ol><p>以下是使用Python实现的代码示例：</p><p>import re</p><p>def reverse_words(sentence):</p><h1 id="使用正则表达式找出所有单词-这里单词定义为由英文字母构成的字符串" tabindex="-1">使用正则表达式找出所有单词，这里单词定义为由英文字母构成的字符串 <a class="header-anchor" href="#使用正则表达式找出所有单词-这里单词定义为由英文字母构成的字符串" aria-label="Permalink to &quot;使用正则表达式找出所有单词，这里单词定义为由英文字母构成的字符串&quot;">​</a></h1><p>words = re.findall(r&#39;[a-zA-Z]+&#39;, sentence)</p><h1 id="反转单词列表" tabindex="-1">反转单词列表 <a class="header-anchor" href="#反转单词列表" aria-label="Permalink to &quot;反转单词列表&quot;">​</a></h1><p>reversed_words = words[::-1]</p><h1 id="使用空格连接反转后的单词列表-形成新的字符串" tabindex="-1">使用空格连接反转后的单词列表，形成新的字符串 <a class="header-anchor" href="#使用空格连接反转后的单词列表-形成新的字符串" aria-label="Permalink to &quot;使用空格连接反转后的单词列表，形成新的字符串&quot;">​</a></h1><p>reversed_sentence = &#39; &#39;.join(reversed_words) return reversed_sentence</p><h1 id="示例输入" tabindex="-1">示例输入 <a class="header-anchor" href="#示例输入" aria-label="Permalink to &quot;示例输入&quot;">​</a></h1><p>input_sentence = input()</p><h1 id="执行函数并打印结果" tabindex="-1">执行函数并打印结果 <a class="header-anchor" href="#执行函数并打印结果" aria-label="Permalink to &quot;执行函数并打印结果&quot;">​</a></h1><p>print(reverse_words(input_sentence))</p><p>这段代码使用了<code>re.findall()</code>函数来查找输入字符串中所有符合条件（由一个或多个英文字母组成）的单词。找到所有单词后，通过切片操作<code>[::-1]</code>来反转单词列表。最后，使用<code>&#39; &#39;.join()</code>方法将反转后的单词列表连接成一个新的字符串，并输出。</p><p>这种方法有效地实现了题目要求的单词倒排功能，同时利用正则表达式轻松处理了非单词字符作为分隔符的情况。</p></div>',1)])])}const u=a(n,[["render",s]]);export{_ as __pageData,u as default};
